const envelope = $json && typeof $json === 'object' ? $json : {};
const raw = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;

const value = (key) => String(raw[key] ?? '').trim();
const segmentoLabels = {
  supermercados: 'Supermercados / Lojas',
  restaurantes: 'Restaurantes / Docerias',
  clinicas: 'Clínicas / Laboratórios',
  varejo: 'Varejo / Franquias',
  outros: 'Outros Processos Manuais'
};
const interesseLabels = {
  'chamaai-food': 'ChamaAí Food (Delivery)',
  'chamaai-filas': 'ChamaAí Gestão de Filas',
  signageflow: 'SignageFlow (Mídia Indoor)',
  'cesta-esperta': 'CestaEsperta (Catálogo, Pedidos e Logística)',
  'sob-medida': 'Sistema Customizado Sob Medida',
  outros: 'Outras dúvidas ou parcerias'
};

const required = ['nome', 'empresa', 'email', 'whatsapp', 'segmento', 'necessidade', 'mensagem'];
const missing = required.filter((key) => !value(key));
if (missing.length) throw new Error('CAMPOS_OBRIGATORIOS_AUSENTES:' + missing.join(','));

const receivedAt = new Date();
const dateTime = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  dateStyle: 'full',
  timeStyle: 'medium'
}).format(receivedAt);

const segmento = segmentoLabels[value('segmento')] || value('segmento');
const interesse = interesseLabels[value('necessidade')] || value('necessidade');
const origem = value('origem') || 'Página não informada';
const whatsappDigits = value('whatsapp').replace(/\D/g, '');
const whatsappInternational = whatsappDigits.startsWith('55') && whatsappDigits.length >= 12
  ? whatsappDigits
  : '55' + whatsappDigits;
const whatsappLink = 'https://wa.me/' + whatsappInternational;

let text = [
  '📥 NOVO CONTATO COMERCIAL — NEXAREIS',
  '',
  '🕒 Data e horário: ' + dateTime,
  '🎯 Interesse: ' + interesse,
  '🏪 Segmento: ' + segmento,
  '',
  '👤 Nome: ' + value('nome'),
  '🏢 Empresa: ' + value('empresa'),
  '✉️ E-mail: ' + value('email'),
  '📱 WhatsApp: ' + value('whatsapp'),
  '🔗 Conversar no WhatsApp: ' + whatsappLink,
  '',
  '💬 Mensagem:',
  value('mensagem'),
  '',
  '🌐 Origem: ' + origem
].join('\n');

if (text.length > 3900) text = text.slice(0, 3880) + '\n\n[Mensagem truncada]';

return [{
  json: {
    whatsappText: text,
    receivedAt: receivedAt.toISOString(),
    dateTime,
    interesse,
    segmento,
    nome: value('nome'),
    empresa: value('empresa'),
    email: value('email'),
    whatsapp: value('whatsapp'),
    whatsappLink,
    mensagem: value('mensagem'),
    origem
  }
}];

const r = $json;
const accepted = typeof r.key?.id === 'string' && r.key.id.trim().length > 0 && r.key.fromMe === true && r.key.remoteJid === '5511937105501@s.whatsapp.net' && ['PENDING','SERVER_ACK','DELIVERY_ACK','READ','PLAYED'].includes(r.status);
return [{json: {ok: accepted, success: accepted, delivery: 'whatsapp', messageId: accepted ? r.key.id : null}}];
